// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(uint256 amount) public {
        // keep the domain wide: any amount (including 0) is admissible
        vm.deal(address(c), amount);
        // the owner recorded at construction is msg.sender of setUp == this test contract
        vm.prank(address(this));
        c.sudicideAnyone();
        // Rule: a successful owner call must have destroyed C, sending its entire
        // balance away, so address(c).balance must be 0 for EVERY amount.
        // The mutant never self-destructs and keeps `amount` (violated when amount > 0).
        assertTrue(address(c).balance == 0, "selfdestruct must drain balance");
    }
}
